Lemma AFlatBuf_consume : forall LB m a F ds k pre bj,
  rw_cells bsegs m a (FlatBufCells (fb_consume F k)) -> fb_ok LB F -> F <> FB_empty -> zlength ds = fb_size F -> 0 <= k <= fb_size F ->
  rw_cells bsegs m (fb_begin F) [CB (Z.to_nat (fb_in F - fb_begin F)) pre; CB (length ds) ds; CB (Z.to_nat (fb_end F - fb_out F)) bj] ->
  addressable m (fb_begin F) (fb_cap F) ->
